    /// </summary>
    /// <remarks>
    /// Source: <c>uSync/v9/ContentTypes/compcorebase.config</c>.
    /// Flow B (agent-authored) — Ola 8.
    /// </remarks>
    public static readonly Guid CompCoreBase =
        Guid.Parse("5e2ec6b8-7f65-4c26-8c20-1b9a72bed2f8");

